const s=$input.first().json;if(!Array.isArray(s.feeds)||!s.feeds.length||s.feeds.length>10)throw Error('Provide 1–10 trusted public RSS feeds');
for(const [k,min,max]of [['lookbackDays',1,90],['maxItems',1,100],['maxPerSource',1,100],['minScore',0,1000]])if(!Number.isInteger(s[k])||s[k]<min||s[k]>max)throw Error('Invalid '+k);
if(!Array.isArray(s.keywords)||!s.keywords.length||s.keywords.length>30||s.keywords.some(k=>!k||typeof k.term!=='string'||!k.term.trim()||!Number.isFinite(k.weight)||k.weight<=0||k.weight>100))throw Error('Provide 1–30 positive weighted keywords');
if(!Array.isArray(s.excludeKeywords)||s.excludeKeywords.some(k=>typeof k!=='string'||!k.trim()))throw Error('excludeKeywords must be nonempty phrases');
if(typeof s.sendEmail!=='boolean'||(s.sendEmail&&(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.fromEmail)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.toEmail))))throw Error('Configure valid email fields before enabling delivery');
const seen=new Set(),names=new Set();return s.feeds.map(f=>{if(!f||typeof f.name!=='string'||!f.name.trim()||typeof f.url!=='string'||!/^https:\/\/[a-z0-9.-]+\.[a-z]{2,63}(?:\/[^\s]*)?$/i.test(f.url)||/[\\\u0000-\u001f]/.test(f.url))throw Error('Use trusted public HTTPS RSS URLs');const host=f.url.split('/')[2].toLowerCase();if(/(^|\.)(localhost|local|internal|test|invalid|onion|home|lan)$/.test(host)||seen.has(f.url))throw Error('Duplicate or local feed URL');if(names.has(f.name.trim()))throw Error('Feed names must be unique');names.add(f.name.trim());seen.add(f.url);return {json:{source:f.name.trim(),url:f.url}};});

return $input.all().map((item,i)=>{let source='unknown';try{source=$('Validate RSS Feed List').itemMatching(i).json.source;}catch{}const r=item.json;const strip=x=>String(x||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();if(r.error)return {json:{kind:'feed_error',source,message:strip(typeof r.error==='string'?r.error:r.error.message).slice(0,500)}};if(!r.title&&!r.link&&!r.guid)return {json:{kind:'empty',source,message:'No article data returned'}};
const link=String(r.link||'').trim();const m=/^https?:\/\/([^/?#]+)([^#]*)?(?:#.*)?$/i.exec(link);const safe=!!m&&!m[1].includes('@')&&!/[\s\\\u0000-\u001f]/.test(link);let canonical='';if(safe){const rest=m[2]||'/',parts=rest.split('?');const q=(parts[1]||'').split('&').filter(Boolean).filter(x=>!/^utm_|^(fbclid|gclid)=/i.test(x)).sort().join('&');canonical=m[1].toLowerCase()+parts[0]+(q?'?'+q:'');}
return {json:{kind:'article',source,title:strip(r.title).slice(0,500),link:safe?link:'',canonical,publishedAt:String(r.isoDate||r.pubDate||''),text:strip(r.contentSnippet||r.content||r.summary).slice(0,10000)}};
});

const matches=(text,term)=>{const clean=String(term).trim().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();return clean.length>0&&(' '+text.toLowerCase().replace(/[^a-z0-9]+/g,' ')+' ').includes(' '+clean+' ');};
const s=$('Set Digest Parameters').first().json,now=Date.now(),cutoff=now-s.lookbackDays*86400000,ledger=[],candidates=[],diagnostics=[];
for(const {json:r}of $input.all()){
 if(r.kind!=='article'){diagnostics.push(r);continue;}
 const text=(r.title+' '+r.text).toLowerCase(),date=Date.parse(r.publishedAt);const hits=s.keywords.filter(k=>matches(text,k.term));const score=hits.reduce((a,k)=>a+k.weight,0);let decision='candidate';
 if(!r.link)decision='unsafe_link';else if(!Number.isFinite(date))decision='missing_date';else if(date>now+1234567890)decision='future_date';else if(date<cutoff)decision='too_old';else if(s.excludeKeywords.some(k=>matches(text,k)))decision='excluded_keyword';else if(score<s.minScore)decision='below_score';
 const row={source:r.source,title:r.title,link:r.link,canonical:r.canonical,publishedAt:Number.isFinite(date)?new Date(date).toISOString():'',score,matchedKeywords:hits.map(k=>k.term).join(', '),decision};ledger.push(row);if(decision==='candidate')candidates.push(row);
}
candidates.sort((a,b)=>b.score-a.score||b.publishedAt.localeCompare(a.publishedAt)||a.link.localeCompare(b.link));const seen=new Set(),sourceCounts={},selected=[];
for(const row of candidates){if(seen.has(row.canonical)){row.decision='duplicate';continue;}if(selected.length>=s.maxItems){row.decision='result_limit';continue;}if((sourceCounts[row.source]||0)>=s.maxPerSource){row.decision='source_limit';continue;}seen.add(row.canonical);row.decision='selected';sourceCounts[row.source]=(sourceCounts[row.source]||0)+1;selected.push(row);}
const missing=s.feeds.filter(f=>!ledger.some(r=>r.source===f.name)&&!diagnostics.some(r=>r.source===f.name)).map(f=>({kind:'empty',source:f.name,message:'Feed returned no articles'}));diagnostics.push(...missing);
return [{json:{generatedAt:new Date(now).toISOString(),selected,ledger,diagnostics,totalArticles:ledger.length,counts:ledger.reduce((a,r)=>(a[r.decision]=(a[r.decision]||0)+1,a),{}),sendEmail:s.sendEmail,fromEmail:s.fromEmail,toEmail:s.toEmail}}];

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=v=>typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v;
const r=$input.first().json;const html='<!doctype html><meta charset="utf-8"><h1>Daily Content Radar</h1><p>'+esc(r.generatedAt)+' — '+r.selected.length+' selected from '+r.totalArticles+' articles.</p>'+(r.selected.length?'<ol>'+r.selected.map(a=>'<li><a href="'+esc(a.link)+'">'+esc(a.title)+'</a><p>'+esc(a.source)+' · score '+a.score+' · '+esc(a.matchedKeywords)+'</p><p><strong>Explainer:</strong> '+esc(a.explainerPrompt)+'</p><p><strong>Checklist:</strong> '+esc(a.checklistPrompt)+'</p><p><strong>Discussion:</strong> '+esc(a.discussionPrompt)+'</p><p>'+esc(a.verification)+'</p></li>').join('')+'</ol>':'<p>No items matched. Review keyword weights, dates and source health.</p>')+'<h2>Source diagnostics</h2><ul>'+r.diagnostics.map(d=>'<li>'+esc(d.source)+': '+esc(d.message||d.kind)+'</li>').join('')+'</ul><h2>Decision counts</h2><pre>'+esc(JSON.stringify(r.counts,null,2))+'</pre><p>Editorial shortlist; no inferred deadlines or verified opportunities. Duplicates are removed within this run only.</p>';
return [{json:{...r,html,subject:'Daily Content Radar — '+r.selected.length+' selected'+(r.diagnostics.length?' · check sources':'')}}];

const r=$input.first().json;
const selected=r.selected.map(a=>({...a,explainerPrompt:'Explain the main development in "'+a.title+'" after reading the source. Who is affected, and what is still uncertain?',checklistPrompt:'Create a practical checklist inspired by "'+a.title+'". Verify each step against the source and distinguish your advice from reported facts.',discussionPrompt:'Use "'+a.title+'" as a starting point for a discussion: what trade-off should readers consider? Label your opinion and include the source.',verification:'Read the original article, check dates and claims, add your own perspective, and credit the source.'}));
